"""Sinh bộ FIXTURE tổng hợp có cùng cấu trúc JSON với LeanDojo Benchmark 4.

Chỉ dùng cho test và chạy thử pipeline offline. Không phải dữ liệu thật, không dùng cho báo cáo.

    python -m tests.fixtures.mini_benchmark --out data/raw/mini_benchmark --n-train 300
"""
from __future__ import annotations

import argparse
import json
import os
import random

# (domain, mẫu goal, tactic kết thúc điển hình) — tactic tương quan với dạng goal để predictor có tín hiệu
PATTERNS = [
    ("Algebra", "a b c : ℤ\n⊢ (a + b) * c = a * c + b * c", "ring"),
    ("Algebra", "x y : ℚ\n⊢ (x - y) ^ 2 = x ^ 2 - 2 * x * y + y ^ 2", "ring"),
    ("Data", "n m : ℕ\nh : n < m\n⊢ n + 1 ≤ m", "omega"),
    ("Data", "l : List ℕ\n⊢ (l ++ []).length = l.length", "simp"),
    ("Order", "a b : ℝ\nh₁ : 0 ≤ a\nh₂ : 0 ≤ b\n⊢ 0 ≤ a * b", "positivity"),
    ("Order", "x y : ℝ\nh : x < y\n⊢ x ≤ y", "linarith"),
    ("Logic", "p q : Prop\nhp : p\nhq : q\n⊢ p ∧ q", "exact"),
    ("Topology", "X : Type\ninst : TopologicalSpace X\nU : Set X\n⊢ IsOpen ∅", "simp"),
]
INTRO_STEPS = ["intro h", "rw [Nat.add_comm]", "simp only [mul_comm]", "constructor", "apply le_of_lt"]


def make_theorem(i: int, rng: random.Random) -> dict:
    domain, goal, finisher = PATTERNS[rng.randrange(len(PATTERNS))]
    n_pre = rng.choice([0, 0, 1, 1, 2, 3])
    states = [f"{goal}  -- v{i % 7}"]
    tactics = []
    for _ in range(n_pre):
        tactics.append(rng.choice(INTRO_STEPS))
        states.append(states[-1] + f" ∧ True{len(states)}")
    tactics.append(finisher)
    states.append("no goals")
    return {
        "url": "https://github.com/leanprover-community/mathlib4",
        "commit": "fixture",
        "file_path": f"Mathlib/{domain}/Fixture{i % 5}.lean",
        "full_name": f"Fixture.{domain}.thm_{i:05d}",
        "traced_tactics": [{"tactic": t, "state_before": states[j], "state_after": states[j + 1]}
                           for j, t in enumerate(tactics)],
    }


def make(out: str, n_train: int = 300, n_eval: int = 60, seed: int = 0) -> str:
    rng = random.Random(seed)
    os.makedirs(out, exist_ok=True)
    i = 0
    for split, n in (("train", n_train), ("val", n_eval), ("test", n_eval)):
        thms = []
        for _ in range(n):
            thms.append(make_theorem(i, rng))
            i += 1
        with open(os.path.join(out, f"{split}.json"), "w", encoding="utf-8") as f:
            json.dump(thms, f, ensure_ascii=False)
    with open(os.path.join(out, "README.txt"), "w", encoding="utf-8") as f:
        f.write("SYNTHETIC FIXTURE generated by tests/fixtures/mini_benchmark.py - not real data.\n")
    return out


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--out", default="data/raw/mini_benchmark")
    ap.add_argument("--n-train", type=int, default=300)
    ap.add_argument("--n-eval", type=int, default=60)
    ap.add_argument("--seed", type=int, default=0)
    a = ap.parse_args()
    print("fixture ->", make(a.out, a.n_train, a.n_eval, a.seed))
